def string_suffix(S: str) -> int:
    total_similarity = 0
    for i in range(len(S)):
        suffix = S[i:]
        similarity = 0
        for j in range(min(len(S), len(suffix))):
            if S[j] == suffix[j]:
                similarity += 1
            else:
                break
        total_similarity += similarity
    return total_similarity
